struct Ring {
    template<typename T>
    static T div(T p, T q, T N) {
        T t = 0, nt = 1, r = N, nr = q;
        while (nr != 0) {
            T q_val = r / nr;
            t -= q_val * nt;
            r -= q_val * nr;
            swap(t, nt);
            swap(r, nr);
        }
        t = (t < 0) ? t + N : t;
        r = (r < 0) ? r + N : r;
        if (gcd(p, N) % r != 0) {
            return 0;
        }
        return (t * p / r) % N;
    }
};

